import { test, expect } from '@playwright/test';

test.describe('Skip Navigation Link Focus Behavior', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should focus on skip navigation link when tabbing from first visible element', async ({ page }) => {
    // Verify skip navigation link is visible and focusable
    const skipNavLink = page.getByRole('navigation', { name: /skip navigation/i });
    await expect(skipNavLink).toBeVisible();
    await expect(skipNavLink).toBeFocused();

    // Verify first visible element is focused before skip link
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeFocused();

    // Verify skip link is the first focusable element
    const firstFocusable = page.getByRole('heading', { name: /section/i });
    await expect(firstFocusable).toBeFocused();

    // Verify skip link receives focus when tabbing
    await page.keyboard.press('Tab');
    await expect(skipNavLink).toBeFocused();

    // Verify skip link is visible and has correct aria-label
    await expect(skipNavLink).toHaveAttribute('aria-label', 'Skip to main content');
  });

  test('should not focus on skip navigation link when tabbing from non-first visible element', async ({ page }) => {
    // Verify skip navigation link is visible and focusable
    const skipNavLink = page.getByRole('navigation', { name: /skip navigation/i });
    await expect(skipNavLink).toBeVisible();

    // Verify first visible element is not focused
    const mainContent = page.getByRole('main');
    await expect(mainContent).not.toBeFocused();

    // Verify skip link is not the first focusable element
    const firstFocusable = page.getByRole('heading', { name: /section/i });
    await expect(firstFocusable).not.toBeFocused();

    // Verify skip link is not focused when tabbing from non-first visible element
    await page.keyboard.press('Tab');
    await expect(skipNavLink).not.toBeFocused();

    // Verify skip link is still visible and has correct aria-label
    await expect(skipNavLink).toHaveAttribute('aria-label', 'Skip to main content');
  });
});
